/**
 * COR-2009 — PageHooks: the signing secret a webhook hook is created with is generated by the
 * Bureau and shown once (`whsec_` and 24 hexadecimal digits), `get` and `list` never carry it, and
 * Replace makes a new one that signs from then on. A delivery that keeps failing is tried up to
 * eight times with backoff, and its attempts keep each try's time and status.
 */
import type { EncryptionKey } from '@lostgradient/cryptography';
import { MemoryStorage } from '@lostgradient/storage';
import { afterEach, beforeAll, describe, expect, it } from 'bun:test';

import { DEFAULT_WEBHOOK_MAX_ATTEMPTS } from '../webhook-notifier.ts';
import { HOOK_SIGNATURE_HEADER, verifyHookSignature } from './hook-signature.ts';
import { HookError } from './hook-types.ts';
import {
  createClock,
  createReceiver,
  fireRunEvents,
  newEncryptionKey,
  openHooksBureau,
  type OpenedHooksBureau,
  SIGNING_SECRET,
  waitForSettledDeliveries,
} from './hooks.test-support.ts';

let key: EncryptionKey;
beforeAll(async () => {
  key = await newEncryptionKey();
});

const opened: OpenedHooksBureau[] = [];
afterEach(async () => {
  for (const bureau of opened.splice(0)) await bureau.dispose();
});

async function open(script?: Parameters<typeof createReceiver>[0]) {
  const receiver = createReceiver(script);
  const { clock, now } = createClock();
  const bureau = await openHooksBureau({
    storage: new MemoryStorage(),
    fetch: receiver.fetch,
    key,
    now,
  });
  opened.push(bureau);
  return { ...bureau, receiver, clock };
}

const WEBHOOK = {
  url: 'https://events.pagerduty.example/v2/enqueue',
  events: ['run.registered'],
  principal: 'api-key:alice',
} as const;

const GENERATED = /^whsec_[0-9a-f]{24}$/;

describe('a webhook hook’s signing secret', () => {
  it('is generated on create when none is given, shown once, and signs the deliveries', async () => {
    const { bureau, receiver, clock } = await open();
    const created = await bureau.hooks!.create(WEBHOOK);

    expect(created.signingSecret).toMatch(GENERATED);
    const secret = created.signingSecret!;
    // Never read back: neither `get` nor `list` carries it.
    expect(await bureau.hooks!.get(created.id)).not.toHaveProperty('signingSecret');
    const listed = await bureau.hooks!.list();
    expect(listed).toHaveLength(1);
    expect(listed[0]).not.toHaveProperty('signingSecret');
    expect(JSON.stringify(listed)).not.toContain(secret);

    await bureau.hooks!.test(created.id);
    const call = receiver.calls[0]!;
    expect(
      verifyHookSignature({
        secret,
        header: call.headers.get(HOOK_SIGNATURE_HEADER)!,
        body: call.body,
        now: clock.milliseconds,
      }),
    ).toEqual({ ok: true });
  });

  it('is never returned when the caller chose it', async () => {
    const { bureau } = await open();
    const created = await bureau.hooks!.create({ ...WEBHOOK, signingSecret: SIGNING_SECRET });
    expect(created).not.toHaveProperty('signingSecret');
  });

  it('is replaced by a new generated one that signs from then on; the old one no longer verifies', async () => {
    const { bureau, receiver, clock } = await open();
    const created = await bureau.hooks!.create(WEBHOOK);
    const replaced = await bureau.hooks!.replaceSigningSecret(created.id, {
      principal: 'api-key:alice',
      expectedRevision: created.revision,
    });

    expect(replaced!.signingSecret).toMatch(GENERATED);
    expect(replaced!.signingSecret).not.toBe(created.signingSecret);
    expect(replaced!.revision).toBe(created.revision + 1);
    expect(await bureau.hooks!.get(created.id)).not.toHaveProperty('signingSecret');

    await bureau.hooks!.test(created.id);
    const call = receiver.calls[0]!;
    const verify = (secret: string) =>
      verifyHookSignature({
        secret,
        header: call.headers.get(HOOK_SIGNATURE_HEADER)!,
        body: call.body,
        now: clock.milliseconds,
      });
    expect(verify(replaced!.signingSecret)).toEqual({ ok: true });
    expect(verify(created.signingSecret!)).toEqual({ ok: false, reason: 'mismatch' });
  });

  it('cannot be replaced on a hook that is not a webhook, nor on a missing one', async () => {
    const { bureau } = await open();
    const notify = await bureau.hooks!.create({
      action: { type: 'notify' },
      events: ['run.registered'],
    });
    expect(notify).not.toHaveProperty('signingSecret');
    const refusal = await bureau.hooks!.replaceSigningSecret(notify.id).catch((error) => error);
    expect(refusal).toBeInstanceOf(HookError);
    expect((refusal as HookError).code).toBe('invalid');
    expect(await bureau.hooks!.replaceSigningSecret('hook-missing')).toBeUndefined();
  });

  it('refuses a replacement against a revision that has moved on', async () => {
    const { bureau } = await open();
    const created = await bureau.hooks!.create(WEBHOOK);
    await bureau.hooks!.update(created.id, { name: 'Page on-call when a run fails' });
    const refusal = await bureau
      .hooks!.replaceSigningSecret(created.id, { expectedRevision: created.revision })
      .catch((error) => error);
    expect((refusal as HookError).code).toBe('stale-revision');
  });
});

describe('a delivery that keeps failing', () => {
  it('is tried up to 8 times with backoff, each try keeping its time and status, then gives up', async () => {
    expect(DEFAULT_WEBHOOK_MAX_ATTEMPTS).toBe(8);
    const { bureau, receiver } = await open(() => new Response('gone', { status: 410 }));
    const hook = await bureau.hooks!.create(WEBHOOK);

    await fireRunEvents(bureau);
    const [delivery] = await waitForSettledDeliveries(bureau, hook.id, 1);

    expect(delivery!.status).toBe('exhausted');
    expect(delivery!.maxAttempts).toBe(8);
    expect(receiver.calls).toHaveLength(8);
    expect(delivery!.attempts.map((attempt) => attempt.number)).toEqual([1, 2, 3, 4, 5, 6, 7, 8]);
    for (const attempt of delivery!.attempts) {
      expect(attempt.outcome).toBe('response');
      expect(attempt.status).toBe(410);
      expect(typeof attempt.startedAt).toBe('number');
    }
    const [summary] = await bureau.hooks!.list();
    expect(summary!.lastDelivery?.status).toBe('exhausted');
    expect(summary!.lastDelivery?.lastAttempt).toMatchObject({ number: 8, status: 410 });
  });
});
